using System.Linq;

namespace FlashColor;

/// <summary>
/// Un filtre de la GPose du jeu, tel que le jeu l'envoie à son shader de filtre (ColorFilter_DarkBlend.shcd) :
/// d'abord une courbe de 256 valeurs, la même pour les trois couleurs, puis une matrice de couleurs 3 × 4.
/// </summary>
/// <param name="Row">Ligne de la feuille ColorFilter du jeu.</param>
/// <param name="Matrix">Les trois lignes de la matrice (rouge, vert, bleu), chacune : 3 couleurs puis décalage.</param>
/// <param name="CurveHex">La courbe, 256 octets en hexadécimal (0 → 0, FF → 1).</param>
internal sealed record GameFilter(uint Row, string EnglishName, string FrenchName, float[] Matrix, string CurveHex)
{
    public string Name => Loc.T(EnglishName, FrenchName);

    public byte[] Curve => Convert.FromHexString(CurveHex);
}

